function Arrow() { return <ArrowRight className="hb-arrow" size={15} />; }

function Header({ locale, setLocale, section }: { locale: Locale; setLocale: (value: Locale) => void; section: Section }) {
  const [open, setOpen] = useState(false);
  const [menuVisible, setMenuVisible] = useState(false);
  const closeTimer = useRef<number | null>(null);
  const fr = locale === "FR";
  const nav: [Section, string][] = [["home", fr ? "Accueil" : "Home"], ["process", fr ? "Processus" : "Process"], ["services", fr ? "Services" : "Services"], ["ecosystem", fr ? "Écosystème" : "Ecosystem"], ["pricing", fr ? "Accès" : "Access"]];
  const openMenu = () => {
    if (closeTimer.current) window.clearTimeout(closeTimer.current);
    setMenuVisible(true);
    window.requestAnimationFrame(() => setOpen(true));
  };
  const closeMenu = () => {
    setOpen(false);
    closeTimer.current = window.setTimeout(() => setMenuVisible(false), 420);
  };
  useEffect(() => {
    if (!menuVisible) return;
    const closeOnEscape = (event: KeyboardEvent) => { if (event.key === "Escape") closeMenu(); };
    document.body.style.overflow = "hidden";
    window.addEventListener("keydown", closeOnEscape);
    return () => { document.body.style.overflow = ""; window.removeEventListener("keydown", closeOnEscape); };
  }, [menuVisible]);
  useEffect(() => () => { if (closeTimer.current) window.clearTimeout(closeTimer.current); }, []);
  return <><header className="hb-header"><div className="hb-shell hb-nav"><Brand /><nav>{nav.map(([key, label]) => { const active = isCurrentPage(section as NavigationPage, key); return <a key={key} className={active ? "active" : ""} aria-current={active ? "page" : undefined} href={paths[key]}>{label}</a>; })}</nav><div className="hb-nav-actions"><button className="hb-locale" onClick={() => setLocale(fr ? "EN" : "FR")}><Languages size={14} />{fr ? "EN" : "FR"}</button><a className="hb-btn hb-btn-primary hb-btn-small" href="/access">{fr ? "Demander l’accès" : "Request access"}<Arrow /></a><button className="hb-menu" onClick={openMenu} aria-label={fr ? "Ouvrir le menu" : "Open menu"} aria-controls="mobile-navigation" aria-expanded={open}><Menu size={20} /></button></div></div></header>{menuVisible && <aside id="mobile-navigation" className={`hb-mobile-menu ${open ? "is-open" : ""}`} role="dialog" aria-modal="true" aria-label={fr ? "Navigation principale" : "Main navigation"}><div className="hb-mobile-menu-head"><Brand /><button className="hb-mobile-close" onClick={closeMenu} aria-label={fr ? "Fermer le menu" : "Close menu"}><X size={21} /></button></div><span className="hb-mobile-orbit" aria-hidden="true" /><p>{fr ? "UN ATELIER NUMÉRIQUE QUI GARDE VOTRE SITE EN MOUVEMENT." : "A DIGITAL ATELIER THAT KEEPS YOUR WEBSITE IN MOTION."}</p><nav>{nav.map(([key, label], index) => { const active = isCurrentPage(section as NavigationPage, key); return <a key={key} className={active ? "active" : ""} aria-current={active ? "page" : undefined} href={paths[key]} onClick={closeMenu}><small>0{index + 1}</small><span>{label}</span><Arrow /></a>; })}</nav><div className="hb-mobile-menu-foot"><button className="hb-locale" onClick={() => setLocale(fr ? "EN" : "FR")}><Languages size={14} />{fr ? "EN" : "FR"}</button><a className="hb-btn hb-btn-primary" href="/access" onClick={closeMenu}>{fr ? "Demander l’accès" : "Request access"}<Arrow /></a></div></aside>}</>;
}

