/* CHAPITRE 01 / interactive project-gallery backdrop: preserves readable editorial copy while the work floats behind it. */
function InteractiveChapter({ fr }: { fr: boolean }) {
  const chapterRef = useRef<HTMLElement | null>(null);
  const [awake, setAwake] = useState(false);
  useEffect(() => {
    const node = chapterRef.current;
    if (!node) return;
    const reveal = new IntersectionObserver(([entry]) => { if (entry.isIntersecting) setAwake(true); }, { threshold: .18 });
    const move = (event: PointerEvent) => {
      const rect = node.getBoundingClientRect();
      const x = ((event.clientX - rect.left) / rect.width - .5) * 2;
      const y = ((event.clientY - rect.top) / rect.height - .5) * 2;
      node.style.setProperty("--chapter-mouse-x", x.toFixed(3));
      node.style.setProperty("--chapter-mouse-y", y.toFixed(3));
    };
    const reset = () => { node.style.setProperty("--chapter-mouse-x", "0"); node.style.setProperty("--chapter-mouse-y", "0"); };
    reveal.observe(node); node.addEventListener("pointermove", move, { passive: true }); node.addEventListener("pointerleave", reset);
    return () => { reveal.disconnect(); node.removeEventListener("pointermove", move); node.removeEventListener("pointerleave", reset); };
  }, []);
  return <section ref={chapterRef} className={`hb-chapter hb-chapter-interactive ${awake ? "is-awake" : ""}`}><div className="hb-chapter-gallery" aria-hidden="true">{ACCESS_PROJECTS.map(([src, name, label], index) => <figure className={`hb-chapter-card hb-chapter-card-${index + 1}`} key={src}><img src={src} alt="" /><div /><small>{name}</small><b>{label}</b></figure>)}<span className="hb-chapter-sweep" /></div><div className="hb-chapter-veil" aria-hidden="true" /><div className="hb-shell hb-chapter-grid hb-chapter-content"><div><span>CHAPITRE 01</span><h2>{fr ? <>VOUS N’OUVREZ<br />PAS UN ÉDITEUR.<br />VOUS OUVREZ<br /><em>UNE CONVERSATION.</em></> : <>YOU DO NOT OPEN<br />AN EDITOR. YOU<br />OPEN A<br /><em>CONVERSATION.</em></>}</h2></div><div><p>{fr ? "Un nouveau service, une image à remplacer, une idée à rendre plus claire : vous le demandez dans votre espace. Nous le prenons, le façonnons, puis le publions. Sans que vous deviez apprendre à construire un site." : "A new service, an image to change, an idea to clarify: you request it in your space. We take it, shape it, and publish it—without asking you to learn how to build a website."}</p><blockquote>{fr ? "Le bon site n’est pas celui que vous arrivez à gérer. C’est celui qui vous laisse gérer votre business." : "The best website is not the one you manage. It is the one that lets you manage your business."}<cite>— HAMACWEB</cite></blockquote><a className="hb-btn hb-btn-dark" href="/process">{fr ? "Voir comment ça avance" : "See how it moves"}<Arrow /></a></div></div></section>;
}

