/* A slow, explanatory in-page product tour: request, studio work, review, then a published page. */
function PresenceTour({ fr }: { fr: boolean }) {
  const tourRef = useRef<HTMLDivElement | null>(null);
  const [stage, setStage] = useState(0);
  useEffect(() => {
    const node = tourRef.current;
    if (!node || window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    let timer: number | undefined;
    const start = () => { setStage(0); timer = window.setInterval(() => setStage((current) => (current + 1) % 4), 6800); };
    const stop = () => { if (timer) window.clearInterval(timer); timer = undefined; };
    const observer = new IntersectionObserver(([entry]) => { if (entry.isIntersecting) start(); else stop(); }, { threshold: .35 });
    observer.observe(node);
    return () => { stop(); observer.disconnect(); };
  }, []);
  const copy = fr ? [
    ["01 / LA DEMANDE", "Vous expliquez simplement ce qui change."],
    ["02 / L’ATELIER", "Notre équipe transforme votre note en travail concret."],
    ["03 / L’APERÇU", "Vous voyez la page avant qu’elle sorte."],
    ["04 / EN LIGNE", "Votre site évolue, sans devenir votre travail."]
  ] : [
    ["01 / THE REQUEST", "You simply explain what changes."],
    ["02 / THE ATELIER", "Our team turns your note into real work."],
    ["03 / THE PREVIEW", "You see the page before it goes out."],
    ["04 / LIVE", "Your site evolves without becoming your work."]
  ];
  const [eyebrow, summary] = copy[stage];
  return <div ref={tourRef} className="hb-presence-tour" data-stage={stage} aria-label={fr ? "Visite animée de l’application HamacWeb" : "Animated tour of the HamacWeb application"}>
    <div className="hb-tour-browser"><header><span><i /><i /><i /></span><b>hamacweb.com / espace</b><em>{fr ? "VISITE GUIDÉE" : "GUIDED TOUR"}</em></header><div className="hb-tour-app"><aside><strong>H</strong><span className={stage === 0 ? "is-active" : ""}>{fr ? "Demandes" : "Requests"}</span><span className={stage === 1 ? "is-active" : ""}>{fr ? "Atelier" : "Atelier"}</span><span className={stage === 2 ? "is-active" : ""}>{fr ? "Aperçus" : "Previews"}</span><span className={stage === 3 ? "is-active" : ""}>{fr ? "En ligne" : "Live"}</span><small>01—04</small></aside><main><div className="hb-tour-heading"><div><span>{eyebrow}</span><b>{stage === 0 ? (fr ? "Votre espace de demande" : "Your request space") : stage === 1 ? (fr ? "Votre demande est en cours" : "Your request is in motion") : stage === 2 ? (fr ? "Votre page est prête à relire" : "Your page is ready to review") : (fr ? "Votre page est maintenant en ligne" : "Your page is now live")}</b></div><i>{stage + 1}/4</i></div><section className="hb-tour-stage"><article className="hb-tour-request"><span>{fr ? "NOUVELLE DEMANDE" : "NEW REQUEST"}</span><b>{fr ? "Ajouter la promo du mois" : "Add the monthly promotion"}</b><p>{fr ? "15 % sur le changement d’huile ce mois-ci." : "15% off oil changes this month."}</p><div><i />{fr ? "Photo-promo.jpg jointe" : "Promo-photo.jpg attached"}</div><button>{fr ? "Envoyer à l’atelier" : "Send to the atelier"}<Arrow /></button></article><article className="hb-tour-work"><span>{fr ? "ATELIER HAMACWEB" : "HAMACWEB ATELIER"}</span><div><i /><b>{fr ? "Contenu structuré" : "Content structured"}<small>{fr ? "Texte, offre et appel à l’action" : "Copy, offer and call to action"}</small></b><em>✓</em></div><div><i /><b>{fr ? "Visuel préparé" : "Visual prepared"}<small>{fr ? "Image et composition de page" : "Image and page composition"}</small></b><em>✓</em></div><div><i /><b>{fr ? "Page assemblée" : "Page assembled"}<small>{fr ? "Contrôle avant aperçu" : "Check before preview"}</small></b><em>✓</em></div></article><article className="hb-tour-preview"><div className="hb-tour-pagebar"><i /><b>{fr ? "VOTRE ENTREPRISE" : "YOUR BUSINESS"}</b><span /></div><div className="hb-tour-page"><div><small>{fr ? "UNE OFFRE DU MOIS" : "A MONTHLY OFFER"}</small><b>{fr ? <>PRENEZ<br />LA ROUTE.</> : <>TAKE<br />THE ROAD.</>}</b><span>{fr ? "Voir l’offre" : "View offer"}</span></div><i /></div><footer><span>{fr ? "Aperçu prêt à approuver" : "Preview ready to approve"}</span><b>{fr ? "Approuver" : "Approve"}</b></footer></article><article className="hb-tour-live"><div><span>{fr ? "MISE À JOUR PUBLIÉE" : "UPDATE PUBLISHED"}</span><b>{fr ? "La promo est visible." : "The offer is live."}</b><p>{fr ? "La page est en ligne. Vous pouvez retourner à votre journée." : "The page is live. You can return to your day."}</p></div><aside><strong>312</strong><span>{fr ? "VISITES CE MOIS" : "VISITS THIS MONTH"}</span><i>+15%</i></aside></article><span className="hb-tour-cursor" aria-hidden="true" /></section><footer className="hb-tour-caption"><span>{summary}</span><b>{fr ? "SUIVANT :" : "NEXT:"} {stage === 0 ? (fr ? "l’atelier prend le relais" : "the atelier takes over") : stage === 1 ? (fr ? "vous recevez un aperçu" : "you receive a preview") : stage === 2 ? (fr ? "vous approuvez" : "you approve") : (fr ? "la prochaine demande" : "the next request")}</b></footer></main></div></div><div className="hb-tour-timeline" aria-hidden="true"><i className={stage >= 0 ? "is-done" : ""} /><i className={stage >= 1 ? "is-done" : ""} /><i className={stage >= 2 ? "is-done" : ""} /><i className={stage >= 3 ? "is-done" : ""} /></div>
  </div>;
}

