function PricingPage({ locale }: { locale: Locale }) { const fr = locale === "FR"; const features = fr ? ["Un site fait sur mesure", "Hébergement sécurisé", "Modifications incluses", "Soutien humain", "Contenu qui évolue", "Accès par demande"] : ["A custom-made website", "Secure hosting", "Updates included", "Human support", "Content that evolves", "Access by request"]; return <><PageIntro eyebrow={fr ? "L’ACCÈS" : "ACCESS"} title={fr ? "UNE CONVERSATION AVANT DE COMMENCER." : "A CONVERSATION BEFORE WE START."} body={fr ? "Chaque accès commence par une lecture attentive de votre activité et de ce qui devrait devenir plus simple." : "Every access request starts with a thoughtful look at your business and what should become simpler."} image={IMG.live} tag="ACCESS / LIMITED" /><section className="hb-pricing"><div className="hb-shell hb-pricing-grid"><div><span className="hb-eyebrow">{fr ? "LE POINT DE DÉPART" : "THE STARTING POINT"}</span><h2>{fr ? "SIMPLE À EXPLIQUER. SIMPLE À SUIVRE." : "SIMPLE TO EXPLAIN. SIMPLE TO FOLLOW."}</h2><p>{fr ? "Vous décrivez votre contexte, votre prochain geste et ce que vous souhaitez éclaircir. L’atelier revient avec une suite claire." : "You describe your context, your next move, and what needs clarity. The atelier comes back with a clear next step."}</p></div><article className="hb-price-card"><span>HAMACWEB / ACCESS</span><div><strong>{fr ? "PAR" : "BY"}<sup>{fr ? " DEMANDE" : " REQUEST"}</sup></strong></div><p>{fr ? "Une réponse adaptée à votre réalité, avant de lancer le travail." : "A response adapted to your reality before work begins."}</p><ul>{features.map((feature) => <li key={feature}><Check size={14} />{feature}</li>)}</ul><a className="hb-btn hb-btn-primary" href="/access">{fr ? "Faire une demande" : "Make a request"}<Arrow /></a></article></div></section><section className="hb-section"><div className="hb-shell"><div className="hb-section-head"><div><span className="hb-eyebrow">{fr ? "EN TOUTE BONNE FOI" : "IN GOOD FAITH"}</span><h2>{fr ? "QUI FAIT LE TRAVAIL?" : "WHO DOES THE WORK?"}</h2></div><p>{fr ? "Le choix dépend surtout de ce que vous voulez garder dans votre journée." : "The choice mostly depends on what you want to keep in your day."}</p></div><div className="hb-compare"><article><span>01 / HAMACWEB</span><h3>{fr ? "Vous demandez. On fait." : "You ask. We do."}</h3><p>{fr ? "Une équipe transforme votre besoin en changement réel." : "A team turns your need into a real change."}</p></article><article><span>02 / DIY</span><h3>{fr ? "Vous construisez." : "You build."}</h3><p>{fr ? "Un bon choix si vous voulez apprendre et garder le temps pour ça." : "A good choice if you want to learn and have the time for it."}</p></article><article><span>03 / AGENCY</span><h3>{fr ? "Vous mandatez." : "You commission."}</h3><p>{fr ? "Un mandat défini, un devis et une nouvelle boucle à chaque modification." : "A defined mandate, a quote, and a new loop for every update."}</p></article></div></div></section></>; }

function ServiceRow({ index, title, body, action, image, locale }: { index: number; title: string; body: string; action: string; image: string; locale: Locale }) {
  const ref = useRef<HTMLElement | null>(null);
  const [revealed, setRevealed] = useState(false);
  useEffect(() => {
    const node = ref.current;
    if (!node) return;
    const observer = new IntersectionObserver(([entry]) => { if (entry.isIntersecting) { setRevealed(true); observer.disconnect(); } }, { threshold: .22 });
    observer.observe(node);
    return () => observer.disconnect();
  }, []);
  const details = getServiceDetails(locale, index);
  return <article ref={ref} tabIndex={0} className={`hb-service-row ${index % 2 ? "is-right" : "is-left"} ${revealed ? "is-revealed" : ""}`}><figure><img src={image} alt="" /><span>0{index + 1}</span></figure><div><small>HAMACWEB / 0{index + 1}</small><h3>{title}</h3><p>{body}</p><div className="hb-service-extra"><span>{locale === "FR" ? "CE QUI BOUGE" : "WHAT MOVES"}</span><ul>{details.map((detail) => <li key={detail}>{detail}</li>)}</ul></div><a className="hb-btn hb-btn-ghost" href={index === 1 || index === 3 ? "/access" : "/process"}>{action}<Arrow /></a></div></article>;
}

