function AccessRequestForm({ fr }: { fr: boolean }) {
  const [status, setStatus] = useState<"idle" | "sending" | "sent" | "error">("idle");
  const [error, setError] = useState("");
  const submit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault(); setStatus("sending"); setError("");
    const data = Object.fromEntries(new FormData(event.currentTarget).entries());
    try {
      const response = await fetch("/api/access-requests", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ ...data, locale: fr ? "FR" : "EN" }) });
      if (!response.ok) { const body = await response.json().catch(() => null); throw new Error(body?.error || "Request error"); }
      setStatus("sent"); event.currentTarget.reset();
    } catch (submissionError) { setError(submissionError instanceof Error ? submissionError.message : "Request error"); setStatus("error"); }
  };
  if (status === "sent") return <div className="hb-form-card hb-success"><span><Check size={32} /></span><h3>{fr ? "SIGNAL REÇU." : "SIGNAL RECEIVED."}</h3><p>{fr ? "Votre demande a été enregistrée. Nous revenons vers vous avec la suite." : "Your request has been recorded. We will come back with the next step."}</p></div>;
  return <form className="hb-form-card" onSubmit={submit}><label>{fr ? "VOTRE PRÉNOM" : "YOUR FIRST NAME"}<input name="name" required maxLength={120} placeholder={fr ? "Marie" : "Marie"} /></label><label>{fr ? "VOTRE ENTREPRISE" : "YOUR BUSINESS"}<input name="business" required maxLength={180} placeholder={fr ? "Le nom de votre business" : "Your business name"} /></label><label>{fr ? "VOTRE COURRIEL" : "YOUR EMAIL"}<input name="email" type="email" required maxLength={320} placeholder="hello@entreprise.com" /></label><label>{fr ? "VOTRE DEMANDE" : "YOUR REQUEST"}<textarea name="message" required minLength={8} maxLength={5000} placeholder={fr ? "J’aimerais un site qui..." : "I would love a website that..."} /></label><input className="hb-honeypot" name="website" tabIndex={-1} autoComplete="off" aria-hidden="true" /><div><small>{fr ? "ACCÈS PAR DEMANDE · SANS ENGAGEMENT" : "ACCESS BY REQUEST · NO COMMITMENT"}</small><button className="hb-btn hb-btn-primary" disabled={status === "sending"}>{status === "sending" ? (fr ? "ENVOI…" : "SENDING…") : <>{fr ? "Envoyer ma demande" : "Send my request"}<Arrow /></>}</button></div>{status === "error" && <p className="hb-form-error" role="alert">{error}</p>}</form>;
}

function AccessPage({ locale }: { locale: Locale }) { const fr = locale === "FR"; const questions = fr ? [["Pourquoi l’accès est-il limité?", "Les demandes sont ouvertes progressivement pour garder le bon contexte autour de chaque activité."], ["Est-ce que je peux demander des changements?", "Oui. C’est précisément le cœur de HamacWeb."], ["Dois-je être à l’aise avec la technologie?", "Non. Vous expliquez ce que vous voulez; l’atelier tient le reste."], ["Comment se passe la suite?", "Nous regardons votre note et revenons avec une prochaine étape claire."]] : [["Why is access limited?", "Requests open gradually so each business keeps the right context."], ["Can I request changes?", "Yes. That is exactly the heart of HamacWeb."], ["Do I need to be comfortable with technology?", "No. You explain what you need; the atelier holds the rest."], ["What happens next?", "We review your note and come back with a clear next step."]]; return <><PageIntro eyebrow={fr ? "ACCÈS PRIVÉ" : "PRIVATE ACCESS"} title={fr ? "PARLEZ-NOUS DE CE QUI DEVRAIT AVANCER." : "TELL US WHAT SHOULD MOVE FORWARD."} body={fr ? "Chaque demande commence par une lecture attentive de votre activité et de ce qui devrait devenir plus simple." : "Every request starts with a thoughtful look at your business and what should become simpler."} image={IMG.support} tag="OPEN / ACCESS" /><section className="hb-contact"><div className="hb-shell hb-contact-grid"><div><span className="hb-eyebrow">{fr ? "UNE VRAIE NOTE" : "A REAL NOTE"}</span><h2>{fr ? "DITES-LE NOUS COMME VOUS LE DIRIEZ À UNE PERSONNE." : "TELL US LIKE YOU WOULD TELL A PERSON."}</h2><p>{fr ? "Pas besoin d’un brief parfait. Trois phrases suffisent pour commencer une bonne conversation." : "You do not need a perfect brief. Three sentences are enough to start a good conversation."}</p><div className="hb-contact-points"><span>01 / {fr ? "VOTRE CONTEXTE" : "YOUR CONTEXT"}</span><span>02 / {fr ? "VOTRE PROCHAIN GESTE" : "YOUR NEXT GESTURE"}</span><span>03 / {fr ? "UNE SUITE CLAIRE" : "A CLEAR NEXT STEP"}</span></div></div><AccessRequestForm fr={fr} /></div></section><section className="hb-faq"><div className="hb-shell"><div className="hb-section-head"><div><span className="hb-eyebrow">{fr ? "LES QUESTIONS" : "THE QUESTIONS"}</span><h2>{fr ? "LES RÉPONSES COURTES." : "THE SHORT ANSWERS."}</h2></div></div><div>{questions.map(([q, a]) => <article key={q}><h3>{q}</h3><p>{a}</p></article>)}</div></div></section></>; }

function LegalPage({ locale, kind }: { locale: Locale; kind: "privacy" | "terms" }) { const fr = locale === "FR"; const privacy = kind === "privacy"; const title = privacy ? (fr ? "CONFIDENTIALITÉ" : "PRIVACY") : (fr ? "CONDITIONS" : "TERMS"); const blocks = privacy ? (fr ? [["Les informations recueillies", "Les coordonnées et le contexte fournis dans une demande servent uniquement à répondre à cette demande et à organiser la suite."], ["Le contrôle", "Vous pouvez nous écrire pour demander la mise à jour ou la suppression des renseignements liés à votre demande."], ["Les traces techniques", "Les cookies essentiels permettent au site de fonctionner. Les choix non essentiels restent désactivés sans accord."]] : [["Information collected", "Contact details and context submitted in a request are used only to respond to that request and organise what comes next."], ["Your control", "You can write to request an update or deletion of information connected to your request."], ["Technical traces", "Essential cookies keep the website working. Non-essential choices stay disabled without consent."]]) : (fr ? [["Utiliser le site", "Vous pouvez consulter ce site et envoyer une demande d’accès en fournissant des renseignements exacts."], ["Le cadre", "Les contenus et les échanges restent soumis au contexte défini avec HamacWeb avant tout travail."], ["Nous joindre", "Pour une question liée au site ou à une demande, utilisez le formulaire d’accès."]] : [["Using the website", "You may browse this website and send an access request by providing accurate information."], ["The framework", "Content and exchanges remain subject to the context agreed with HamacWeb before work begins."], ["Contact", "For a question about the website or a request, use the access form."]]); return <section className="hb-legal-page"><div className="hb-shell"><span className="hb-eyebrow">HAMACWEB / {title}</span><h1>{title}</h1><p className="hb-legal-lead">{fr ? "Une information claire pour comprendre comment le site et les demandes sont traités." : "Clear information about how the website and access requests are handled."}</p><div className="hb-legal-blocks">{blocks.map(([heading, text]) => <article key={heading}><h2>{heading}</h2><p>{text}</p></article>)}</div><a className="hb-btn hb-btn-ghost" href="/">{fr ? "Retour à l’accueil" : "Back home"}</a></div></section>; }

function CookieBanner({ fr }: { fr: boolean }) { const [visible, setVisible] = useState(() => window.localStorage.getItem("hamacweb-cookie-choice") === null); const choose = (choice: string) => { window.localStorage.setItem("hamacweb-cookie-choice", choice); setVisible(false); }; if (!visible) return null; return <aside className="hb-cookie" role="dialog" aria-label={fr ? "Choix des cookies" : "Cookie choices"}><p>{fr ? "Nous utilisons les cookies essentiels pour faire fonctionner ce site. Les options non essentielles restent désactivées sans votre accord." : "We use essential cookies to operate this website. Non-essential choices remain disabled without your consent."}</p><div><a href="/privacy">{fr ? "En savoir plus" : "Learn more"}</a><button type="button" onClick={() => choose("refused")}>{fr ? "Refuser" : "Refuse"}</button><button type="button" onClick={() => choose("accepted")}>{fr ? "Accepter" : "Accept"}</button></div></aside>; }

export default function Home() {
  const [location] = useLocation(); const [locale, setLocale] = useState<Locale>(() => window.localStorage.getItem("hamacweb-locale") === "EN" ? "EN" : "FR");
  const section: Section = location === "/process" ? "process" : location === "/ecosystem" ? "ecosystem" : location === "/pricing" ? "pricing" : location === "/services" ? "services" : location === "/access" ? "access" : location === "/privacy" ? "privacy" : location === "/terms" ? "terms" : "home";
  useEffect(() => { document.documentElement.lang = locale === "FR" ? "fr-CA" : "en"; window.scrollTo({ top: 0, behavior: "instant" as ScrollBehavior }); }, [location, locale]);
  useEffect(() => { window.localStorage.setItem("hamacweb-locale", locale); }, [locale]);
  return <div className="hb-site"><Header locale={locale} setLocale={setLocale} section={section} /><main key={`${section}-${locale}`} className="hb-page-transition" aria-live="polite">{section === "home" && <HomePage locale={locale} />}{section === "process" && <ProcessPage locale={locale} />}{section === "ecosystem" && <EcosystemPage locale={locale} />}{section === "pricing" && <PricingPage locale={locale} />}{section === "services" && <ServicesPage locale={locale} />}{section === "access" && <AccessPage locale={locale} />}{section === "privacy" && <LegalPage locale={locale} kind="privacy" />}{section === "terms" && <LegalPage locale={locale} kind="terms" />}</main><Footer locale={locale} /><CookieBanner fr={locale === "FR"} /></div>;
}
